import numpy as np
from scipy.optimize import curve_fit
bt=[t**k for k in range(8)]
cols=[P**j*b for j in range(4) for b in bt]
X=np.column_stack(cols)
c,_,_,_=np.linalg.lstsq(X,dP_dt,rcond=None)
grid=np.linspace(0.5,12,200)
g0=sum(c[k]*grid**k for k in range(8))
g3=sum(c[24+k]*grid**k for k in range(8))
forms={
 'A*(1-exp(-kt))+B': lambda x,A,k,B: -A*(1-np.exp(-k*x))+B,
 'A*t/(K+t)': lambda x,A,K,B: -A*x/(K+x)+B,
 'A*(1-exp(-kt))^2': lambda x,A,k,B: -A*(1-np.exp(-k*x))**2+B,
 'A*exp(-k/t)': lambda x,A,k,B: -A*np.exp(-k/x)+B,
 'A*tanh(kt)': lambda x,A,k,B: -A*np.tanh(k*x)+B,
}
for n,f in forms.items():
    try:
        p,_=curve_fit(f,grid,g0,p0=[7.5,0.5,0],maxfev=20000)
        print('g0',n,np.round(p,4), np.max(abs(f(grid,*p)-g0)))
    except Exception as e: print(n,e)
